(()=>{
const worlds={auto:{image:'assets/automotive-premium.webp',alt:'Performance coupe on a mountain road',kicker:'AUTOMOTIVE / GASOLINE ENGINE OILS',title:'Every journey.<br><em>A higher standard.</em>',description:'Discover gasoline engine oils, transmission fluids, coolants and car care for the road ahead.',filter:'automotive',cta:'Explore automotive',product:'assets/stark-render.webp',productAlt:'Petrovöll STÄRK fully synthetic engine oil',family:'STÄRK',familyType:'FULLY SYNTHETIC ENGINE OIL'},diesel:{image:'assets/heavy-duty-premium.webp',alt:'Long-haul truck travelling on a mountain highway',kicker:'HEAVY DUTY / DIESEL ENGINE OILS',title:'Demanding days.<br><em>Keep moving.</em>',description:'Explore the VIRÖ-TEC diesel engine oil family, alongside other Petrovöll diesel formulations.',filter:'diesel',cta:'Explore diesel oils',product:'assets/viro-transparent.webp',productAlt:'Petrovöll VIRÖ-TEC diesel engine oil',family:'VIRÖ-TEC',familyType:'DIESEL ENGINE OIL'},industrial:{image:'assets/bottling-premium.webp',alt:'Illustrative automated lubricant production equipment',kicker:'INDUSTRIAL / MACHINERY & EQUIPMENT',title:'Behind progress.<br><em>There is precision.</em>',description:'Hydraulic, gear, compressor and other industrial oils for the machinery that powers your business.',filter:'industrial',cta:'Explore industrial oils',product:'assets/hydkon-transparent.webp',productAlt:'Petrovöll HYDKÖN hydraulic oil packaging',family:'HYDKÖN',familyType:'HYDRAULIC OIL'},marine:{image:'assets/marine-editorial.webp',alt:'Ocean-going vessel travelling at sea',kicker:'MARINE / OPEN-WATER APPLICATIONS',title:'Beyond the horizon.<br><em>A world in motion.</em>',description:'Explore Petrovöll marine cylinder, trunk piston and outboard oil formulations.',filter:'marine',cta:'Explore marine oils',product:null,family:'MARINEÖL',familyType:'THE MARINE OIL FAMILY'}};
const $=s=>document.querySelector(s),tabs=[...document.querySelectorAll('[data-world]')],images=[...document.querySelectorAll('.world-background')];const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;let current='auto',pending=null,activeImage=0,request=0;Object.values(worlds).forEach(w=>{const preload=new Image();preload.src=w.image});
function show(key){if(key===current||key===pending)return;pending=key;const id=++request,world=worlds[key],next=1-activeImage,img=images[next];img.onload=()=>{if(id!==request)return;img.onload=null;images[activeImage].classList.remove('on');img.classList.add('on');img.alt=world.alt;img.removeAttribute('aria-hidden');images[activeImage].setAttribute('aria-hidden','true');activeImage=next;current=key;pending=null;$('#world-kicker').textContent=world.kicker;$('#world-headline').innerHTML=world.title;$('#world-description').textContent=world.description;$('#world-cta').innerHTML=world.cta+' <span>↗</span>';$('#world-cta').dataset.filter=world.filter;const pack=$('#world-pack');pack.style.display=world.product?'block':'none';if(world.product){pack.src=world.product;pack.alt=world.productAlt}$('#world-family').textContent=world.family;$('#world-family-type').textContent=world.familyType;$('.world-product').classList.toggle('marine-world',!world.product);$('#world-counter').textContent=String(tabs.findIndex(t=>t.dataset.world===key)+1).padStart(2,'0')+' / 04';$('#world-panel').setAttribute('aria-labelledby','world-tab-'+key);tabs.forEach(t=>{const selected=t.dataset.world===key;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1});if(!reducedMotion){img.getAnimations().forEach(a=>a.cancel());img.animate([{clipPath:'inset(0 0 0 100%)'},{clipPath:'inset(0 0 0 0%)'}],{duration:850,easing:'cubic-bezier(.22,1,.36,1)'});['.world-content','.world-product'].forEach(selector=>{const el=$(selector);el.getAnimations().forEach(a=>a.cancel());el.animate([{opacity:0,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:650,easing:'cubic-bezier(.22,1,.36,1)'})})}};img.onerror=()=>{if(id===request){pending=null;img.onload=null;img.onerror=null;img.src=images[activeImage].src;current=key;$('#world-cta').dataset.filter=world.filter;$('#world-description').textContent=world.description;}};img.src=world.image;if(img.complete&&img.naturalWidth)img.onload();}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>show(tab.dataset.world));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;else if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();tabs[n].focus();show(tabs[n].dataset.world)})});
if(!reducedMotion){const sequence=$('.world-sequence'),card=$('.application-studio');let raf=0;function update(){raf=0;const r=sequence.getBoundingClientRect(),top=innerWidth<=700?105:160,p=Math.max(0,Math.min(1,(top-r.top)/Math.max(1,r.height-card.offsetHeight)));if(r.bottom>top&&r.top<innerHeight){show(tabs[Math.min(3,Math.floor(p*4))].dataset.world);card.style.setProperty('--world-progress',p)}}function navigate(i){const top=innerWidth<=700?105:160,r=sequence.getBoundingClientRect();scrollTo({top:scrollY+r.top-top+(r.height-card.offsetHeight)*(i+.12)/4,behavior:'smooth'})}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>navigate(i));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%4;else if(e.key==='ArrowLeft')n=(i+3)%4;else if(e.key==='Home')n=0;else if(e.key==='End')n=3;else return;navigate(n)})});addEventListener('scroll',()=>{if(!raf)raf=requestAnimationFrame(update)},{passive:true});addEventListener('resize',()=>{if(!raf)raf=requestAnimationFrame(update)},{passive:true});update()}
})();
